import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  // IoT Devices Data (Asliyat mein ye database se aata hai)
// 1. Initial 10 devices ka array banate hain (Riyadh, Dubai, NEOM mix)
// 1. Shuruat mein sirf 3 main devices rakhein
const [iotDevices, setIotDevices] = useState([
  { id: "IOT-RX-01", name: "Riyadh Hub", status: "Online", risk: "Low" },
  { id: "IOT-DXB-02", name: "Dubai Gateway", status: "Online", risk: "Low" },
  { id: "IOT-NEOM-03", name: "NEOM Sensor", status: "Online", risk: "Low" }
]);

// 2. Naya Device dhoondne ka logic (Discovery Simulation)
const discoverNewDevice = () => {
  const regions = ["Riyadh", "Dubai", "Abu Dhabi", "NEOM"];
  const types = ["Camera", "Power Grid", "Water Sensor", "Smart Light"];

  const newDevice = {
    id: `IOT-${Math.floor(Math.random() * 1000)}`,
    name: `${regions[Math.floor(Math.random() * 4)]} ${types[Math.floor(Math.random() * 4)]}`,
    status: "Online",
    risk: Math.random() > 0.8 ? "Medium" : "Low", // 20% chance of medium risk
    firmware: "v1." + Math.floor(Math.random() * 9)
  };

  // Naya device list mein add karein (Max 12 devices rakhte hain screen par)
  setIotDevices(prev => [newDevice, ...prev].slice(0, 12));
};

// 3. useEffect mein timer lagayein
useEffect(() => {
  const discoveryTimer = setInterval(discoverNewDevice, 10000); // Har 10 sec mein naya device dikhega
  return () => clearInterval(discoveryTimer);
}, []);

  const fetchThreats = async () => {
    try {
      const res = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: `192.168.1.${Math.floor(Math.random() * 255)}`,
        packet_size: Math.floor(Math.random() * 8000),
        request_count: Math.floor(Math.random() * 2000)
      });

      setThreatData(res.data);
      setLoading(false);

      if (res.data.is_anomaly) {
        setAlerts(prev => [{ id: Date.now(), ...res.data, time: new Date().toLocaleTimeString() }, ...prev].slice(0, 6));
      }
    } catch (err) {
      console.error("ML Engine Connection Error", err);
    }
  };

  useEffect(() => {
    const timer = setInterval(fetchThreats, 5000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div style={{ backgroundColor: '#010409', color: '#c9d1d9', minHeight: '100vh', padding: '25px', fontFamily: 'Arial' }}>

      {/* 1. Header Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '15px' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ CyberGuard AI | Smart City Control Center</h2>
        <div style={{ textAlign: 'right', fontSize: '12px' }}>
          <span style={{ color: '#3fb950' }}>● SOC LIVE</span> | UAE-KSA Region
        </div>
      </div>

      {/* 2. IoT Assets Section (NEW) */}
      <h3 style={{ marginTop: '25px', fontSize: '18px', color: '#8b949e' }}>🌐 IoT Infrastructure Assets</h3>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px', marginTop: '10px' }}>
        {iotDevices.map(device => (
          <div key={device.id} style={{ background: '#0d1117', border: '1px solid #30363d', padding: '15px', borderRadius: '8px', borderLeft: `5px solid ${device.status === 'Online' ? '#3fb950' : '#f85149'}` }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <strong>{device.name}</strong>
              <span style={{ fontSize: '10px', color: '#8b949e' }}>{device.id}</span>
            </div>
            <p style={{ margin: '10px 0 5px 0', fontSize: '13px' }}>Status: {device.status}</p>
            <p style={{ margin: 0, fontSize: '11px', color: device.risk === 'Critical' ? '#f85149' : '#8b949e' }}>
              Risk Level: {device.risk} | FW: {device.firmware}
            </p>
          </div>
        ))}
      </div>

      {/* 3. Live AI Analysis Section */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '30px' }}>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Current Traffic Node</h4>
          {loading ? <p>Scanning Network...</p> : (
            <p style={{ fontSize: '20px', color: threatData.is_anomaly ? '#f85149' : '#3fb950' }}>
              {threatData.is_anomaly ? '⚠️ THREAT IN ' : '✅ SECURE: '} {threatData.location.toUpperCase()}
            </p>
          )}
        </div>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Automated Defense</h4>
          <p style={{ fontSize: '14px' }}>Recommendation: <strong>{threatData?.recommendation || 'Analyzing...'}</strong></p>
          <button style={{ background: '#238636', color: 'white', border: 'none', padding: '5px 12px', borderRadius: '4px', marginTop: '5px', cursor: 'pointer' }}>Deploy Firewall Patch</button>
        </div>
      </div>

      {/* 4. Threat Logs Table */}
      <div style={{ marginTop: '30px', background: '#0d1117', border: '1px solid #30363d', borderRadius: '10px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ background: '#161b22', textAlign: 'left', color: '#8b949e' }}>
            <tr>
              <th style={{ padding: '12px' }}>Time</th>
              <th style={{ padding: '12px' }}>Type</th>
              <th style={{ padding: '12px' }}>Severity</th>
              <th style={{ padding: '12px' }}>Location</th>
            </tr>
          </thead>
          <tbody>
            {alerts.map(alert => (
              <tr key={alert.id} style={{ borderBottom: '1px solid #21262d' }}>
                <td style={{ padding: '12px', fontSize: '12px' }}>{alert.time}</td>
                <td style={{ padding: '12px' }}>{alert.analysis_report}</td>
                <td style={{ padding: '12px' }}>
                  <span style={{ background: alert.threat_level === 'Critical' ? '#490000' : '#3b2300', color: alert.threat_level === 'Critical' ? '#ffa1a1' : '#ffab70', padding: '2px 8px', borderRadius: '10px', fontSize: '11px' }}>
                    {alert.threat_level}
                  </span>
                </td>
                <td style={{ padding: '12px' }}>{alert.location}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Dashboard;
